PREFIX crm: <http://www.cidoc-crm.org/cidoc-crm/>
SELECT ?title ?maker WHERE {
  ?object crm:P48_has_current_or_former_identifier "A 10056" .
  OPTIONAL { ?object crm:P102_has_title ?title . }
  OPTIONAL { ?object crm:P14_carried_out_by ?maker_uri .
             ?maker_uri rdfs:label ?maker . }
}

